                post_hook={
                    "sql": "CREATE OR REPLACE TABLE ct_click_charge AS ( WITH CT_Clicked_events AS ( SELECT TRY_TO_DATE(SUBSTR(ts, 1, 8), \'YYYYMMDD\') AS click_date, TRY_TO_TIME(SUBSTR(ts, 9, 6), \'HHMISS\') AS click_time, SUBSTRING(\"eventProps.Campaign id\", 1, POSITION(\'_\' IN \"eventProps.Campaign id\") - 1) as C_id, \"eventProps.Campaign type\" AS campaign_channel, \"profile.phone\" as unformatted_phone, \'+\' || unformatted_phone AS phone, \"profile.name\" AS profile_name FROM SNITCH_DB.MAPLEMONK.snitch_db_ct_clicked_events WHERE \"eventProps.Campaign type\" IN (\'Sms\', \'WhatsApp\', \'Push\', \'Email\') AND C_id NOT IN (\'1753099592\', \'1753100151\', \'1753100666\', \'1753175787\', \'1753101169\', \'1753101430\', \'1753253552\', \'1753254018\', \'1753254120\', \'1753339568\', \'1753339471\', \'1753264726\', \'1753957559\', \'1754053751\', \'1754053644\', \'1753350802\', \'1753351025\', \'1753356912\', \'1753356978\', \'1753256023\', \'1752834990\', \'1754053876\', \'1752136011\', \'1751022333\', \'1754054106\', \'1755008860\', \'1738771106\', \'1743780334\', \'1744023026\', \'1737203919\', \'1743826165\', \'1738829230\', \'1744024889\', \'1748166392\', \'1755065366\', \'1740978249\', \'1753166642\', \'1739856954\', \'1741259483\', \'1743825958\', \'1746798665\', \'1743780087\', \'1747825397\', \'1746790020\', \'1738909183\', \'1746788998\', \'1747824886\', \'1741166678\', \'1741168362\', \'1744025425\', \'1737004843\', \'1737005227\', \'1743779275\', \'1743779146\', \'1744023956\', \'1737203875\', \'1743779011\', \'1746007871\', \'1743825792\', \'1744024451\', \'1739795074\', \'1738829398\', \'1741163643\', \'1744023687\', \'1744022795\', \'1744025675\', \'1737204081\', \'1743690450\',\'1737005227\',\'1737004843\',\'1738771106\',\'1747733352\',\'1754054106\',\'1738909183\',\'1741163643\',\'1741169554\',\'1737203875\',\'1755065366\',\'1744025675\',\'1744023687\',\'1756881109\',\'1746007871\',\'1753256023\',\'1748335275\',\'1752136011\',\'1737203919\',\'175