snitch.com\')) AND \"eventProps.Campaign labels\" not ilike \'%customer support%\' and \"eventProps.Campaign labels\" not ilike \'%offline%\' QUALIFY ROW_NUMBER() OVER ( PARTITION BY phone, click_date, click_time ORDER BY click_date DESC NULLS LAST, click_time DESC NULLS LAST) = 1 UNION ALL SELECT CASE WHEN LENGTH(SPLIT_PART(click_date, \'/\', 3)) = 2 THEN TO_DATE( SPLIT_PART(click_date, \'/\', 1) || \'/\' || SPLIT_PART(click_date, \'/\', 2) || \'/20\' || SPLIT_PART(click_date, \'/\', 3), \'DD/MM/YYYY\' ) ELSE TO_DATE(click_date, \'DD/MM/YYYY\') END AS click_date, click_time, TO_VARCHAR(c_id) AS c_id, campaign_channel, unformatted_phone, \'+\' || unformatted_phone AS phone, NULL AS profile_name FROM wa_cheatsheet_clicked_users ), Shopify_charged_data AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, Customer_id, order_name, order_timestamp::date as charged_date, COUNT(LINE_ITEM_ID) as qty, SUM(gross_sales) AS total_sales, SUM(SLASHED_DISCOUNT) AS total_sl_discount, SUM(DISCOUNT) AS total_discount FROM SNITCH_DB.MAPLEMONK.FACT_ITEMS_SNITCH WHERE order_timestamp::date > \'2025-01-01\' GROUP BY \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10), Customer_id, order_name, order_timestamp::date ), Click_charge_mapped_Beta AS ( SELECT a.*, b.* FROM SHOPIFY_CHARGED_DATA a LEFT JOIN CT_Clicked_events b ON b.phone = a.phone_no AND Charged_date >= click_date AND CASE WHEN b.campaign_channel = \'Push\' THEN DATEDIFF(days, b.Click_date, a.charged_date) <= 3 WHEN b.campaign_channel = \'WhatsApp\' THEN DATEDIFF(days, b.Click_date, a.charged_date) <= 7 WHEN b.campaign_channel = \'Sms\' THEN DATEDIFF(days, b.Click_date, a.charged_date) <= 7 WHEN b.campaign_channel = \'Email\' THEN DATEDIFF(days, b.Click_date, a.charged_date) <= 7 ELSE DATEDIFF(days, b.Click_date, a.charged_date) <= 3 END WHERE b.Click_date IS NOT Null ), click_charge_final AS ( SELECT * FROM Click_charge_mapped_Beta QUALIFY ROW_NUMBER() OVER ( PARTITION BY Phone_no, order_name ORDER BY click_date DESC NULLS LAST, click_time DESC NULLS LAST) = 1 ) SELECT ccf.* FROM click_charge_final ccf ); CREATE OR REPLACE TABLE campaign_labels_cleaned AS ( WITH raw AS ( SELECT COALESCE( TRY_TO_DATE(a.run_date, \'DD/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY/MM/DD\'), TRY_TO_DATE(a.RUN_DATE, \'D/M/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'D/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY-M-D\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY-MM-DD\'), TRY_TO_DATE(a.RUN_DATE, \'MM/DD/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD-MM-YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'MM-DD-YYYY\') ) AS run_date, ROUND(a.CAMPAIGN_ID,0) AS campaign_id, a.CHANNEL AS channel, MAX(a.CAMPAIGN_NAME) AS campaign_name, MAX(a.LABELS) AS campaign_labels, MAX(CONCAT_WS(CHAR(10)||CHAR(10), a.TITLE, a.MESSAGE)) AS details, MAX(a.who_query) AS segment, SUM(TRY_TO_NUMBER(a.total_sent_users)) AS total_sent_users, SUM(TRY_TO_NUMBER(a.total_clicked_users)) AS total_clicked_users, SUM(TRY_TO_NUMBER(a.total_viewed_users)) AS total_viewed_users, SUM(TRY_TO_NUMBER(a.total_delivered_users)) AS total_delivered_users, SUM(TRY_TO_NUMBER(a.total_sent_events)) AS total_sent_events, SUM(TRY_TO_NUMBER(a.total_viewed_events)) AS total_viewed_events, SUM(TRY_TO_NUMBER(a.total_clicked_events)) AS total_clicked_events, SUM(TRY_TO_NUMBER(a.total_delivered_events)) AS total_delivered_events FROM snitch_db.maplemonk.CT_CLEVERTAP_DB a WHERE a.channel IN (\'Sms\',\'Push Notification\',\'WhatsApp\') AND a.campaign_id NOT IN (\'1753099592\',\'1753100151\',\'1753100666\',\'1753175787\',\'1753101169\',\'1753101430\',\'1753253552\',\'1753254018\',\'1753254120\',\'1753339568\',\'1753339471\',\'1753264726\',\'1753957559\',\'1754053751\',\'1754053644\',\'1753350802\',\'1753351025\',\'1753356912\',\'1753356978\',\'1753256023\',\'1752834990\',\'1754053876\',\'1752136011\',\'1751022333\',\'1754054106\',\'1755008860\',\'1738771106\',\'1743780334\',\'1744023026\',\'1737203919\',\'1743826165\',\'1738829230\',\'1744024889\',\'1748166392\',\'1755065366\',\'1740978249\',\'1753166642\',\'1739856954\',\'1741259483\',\'1743825958\',\'1746798665\',\'1743780087\',\'1747825397\',\'1746790020\',\'1738909183\',\'1746788998\',\'1747824886\',\'1741166678\',\'1741168362\',\'1744025425\',\'1737004843\',\'1737005227\',\'1743779275\',\'1743779146\',\'1744023956\',\'1737203875\',\'1743779011\',\'1746007871\',\'1743825792\',\'1744024451\',\'1739795074\',\'1738829398\',\'1741163643\',\'1744023687\',\'1744022795\',\'1744025675\',\'1737204081\',\'1743690450\') GROUP BY run_date, a.CAMPAIGN_ID, a.CHANNEL UNION ALL SELECT COALESCE( TRY_TO_DATE(a.run_date, \'DD/MM/YY\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY/MM/DD\'), TRY_TO_DATE(a.RUN_DATE, \'D/M/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'D/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY-M-D\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY-MM-DD\'), TRY_TO_DATE(a.RUN_DATE, \'MM/DD/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD-MM-YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'MM-DD-YYYY\') ) AS run_date, ROUND(a.CAMPAIGN_ID,0) AS campaign_id, a.CHANNEL AS channel, MAX(a.CAMPAIGN_NAME) AS campaign_name, MAX(a.LABELS) AS campaign_labels, MAX(CONCAT_WS(CHAR(10)||CHAR(10), a.TITLE, a.MESSAGE)) AS details, MAX(a.who_query) AS segment, SUM(TRY_TO_NUMBER(a.total_sent_users)) AS total_sent_users, SUM(TRY_TO_NUMBER(a.total_clicked_users)) AS total_clicked_users, SUM(TRY_TO_NUMBER(a.total_viewed_users)) AS total_viewed_users, SUM(TRY_TO_NUMBER(a.total_delivered_users)) AS total_delivered_users, SUM(TRY_TO_NUMBER(a.total_sent_events)) AS total_sent_events, SUM(TRY_TO_NUMBER(a.total_viewed_events)) AS total_viewed_events, SUM(TRY_TO_NUMBER(a.total_clicked_events)) AS total_clicked_events, SUM(TRY_TO_NUMBER(a.total_delivered_events)) AS total_delivered_events FROM SNITCH_DB.MAPLEMONK.CT_CAMPAIGNS_JULY_AUG a WHERE a.channel IN (\'Sms\',\'Push Notification\',\'WhatsApp\') AND a.campaign_id NOT IN (\'1753099592\',\'1753100151\',\'1753100666\',\'1753175787\',\'1753101169\',\'1753101430\',\'1753253552\',\'1753254018\',\'1753254120\',\'1753339568\',\'1753339471\',\'1753264726\',\'1753957559\',\'1754053751\',\'1754053644\',\'1753350802\',\'1753351025\',\'1753356912\',\'1753356978\',\'1753256023\',\'1752834990\',\'1754053876\',\'1752136011\',\'1751022333\',\'1754054106\',\'1755008860\',\'1738771106\',\'1743780334\',\'1744023026\',\'1737203919\',\'1743826165\',\'1738829230\',\'1744024889\',\'1748166392\',\'1755065366\',\'1740978249\',\'1753166642\',\'1739856954\',\'1741259483\',\'1743825958\',\'1746798665\',\'1743780087\',\'1747825397\',\'1746790020\',\'1738909183\',\'1746788998\',\'1747824886\',\'1741166678\',\'1741168362\',\'1744025425\',\'1737004843\',\'1737005227\',\'1743779275\',\'1743779146\',\'1744023956\',\'1737203875\',\'1743779011\',\'1746007871\',\'1743825792\',\'1744024451\',\'1739795074\',\'1738829398\',\'1741163643\',\'1744023687\',\'1744022795\',\'1744025675\',\'1737204081\',\'1743690450\') GROUP BY run_date, a.CAMPAIGN_ID, a.CHANNEL ), tokens AS ( SELECT r.campaign_id, r.run_date, r.channel, t.index AS pos, LOWER( TRIM( REPLACE(REPLACE(REPLACE(t.value::string,\'[\',\'\'),\']\',\'\'),\'\"\',\'\') ) ) AS token FROM raw r, LATERAL SPLIT_TO_TABLE( REPLACE(r.campaign_labels, \'|\', \',\'), \',\' ) t WHERE TRIM(t.value::string) <> \'\' ), tok AS ( SELECT campaign_id, run_date, channel, pos, token, LEAD(token) OVER (PARTITION BY campaign_id, run_date ORDER BY pos) AS next_token FROM tokens ), classified AS ( SELECT campaign_id, run_date, channel, token, CASE WHEN token IN (\'active new\',\'active a2c users (no purchase yet)\', \'active new users (no purchase yet)\') THEN \'Active new users (no purchase yet)\' WHEN token IN (\'add to cart\',\'recent a2c users\',\'recent a2c app users (under 45 days)\') THEN \'Recent A2C app users (under 45 days)\' WHEN token IN (\'recent a2c web users (under 45 days)\') THEN \'Recent a2c web users (under 45 days)\' WHEN token IN (\'recent app users\',\'app users less than 180 days\', \'recent app users (under 180 days)\') THEN \'Recent app users (under 180 days)\' WHEN token = \'app users less than 365 days\' THEN \'Recent app users (under 365 days)\' WHEN token IN (\'app users less than 90 days\', \'recent app users (under 90 days)\') THEN \'Recent app users (under 90 days)\' WHEN token IN (\'recent app users (45 days)\', \'recent app users (under 45 days)\',\'recent app users under 45 days\',\'recent app users less than 45 days\',\'recent shoppers (less than 30 days)\', \'recent purchasers\', \'active existing\') THEN \'Recent app users (under 45 days)\' WHEN token IN (\'online + offline\',\'offline to online\',\'offline to online shoppers\',\'offline\') THEN \'Offline to online shoppers\' WHEN token IN (\'recent inactive\',\'recent shoppers (less than 90 days)\', \'recent shoppers (30 - 90 days)\') THEN \'Recent shoppers (30 - 90 days)\' WHEN token IN (\'mid recent\', \'recent shoppers (90 - 180 days)\') THEN \'Recent shoppers (90 - 180 days)\' WHEN token IN (\'shoppers less than 360 days\', \'all shoppers\') THEN \'All shoppers\' WHEN token IN (\'lost customers\', \'dormant shoppers (over 180 days)\') THEN \'Dormant shoppers (over 180 days)\' WHEN token IN (\'birthday\',\'discount shoppers\') THEN \'Discount shoppers\' WHEN token IN (\'regional\',\'regional shoppers\') THEN \'Regional shoppers\' WHEN token IN (\'loyal customers\',\'snitch x\',\'x members\',\'x post enrollment\', \'X Perks\') THEN \'X members\' WHEN token IN (\'x eligible\',\'x activation\') THEN \'X eligible\' WHEN token IN (\'all\', \'xs\',\'s\',\'m\',\'l\',\'xl\',\'xxl\',\'large\',\'all users\') THEN \'All users\' WHEN token IN (\'snitch plus\', \'snitch plus shoppers\') THEN \'Snitch Plus shoppers\' WHEN token IN (\'best shoppers (high rfm)\',\'rfm\',\'high rfm\', \'best customers\') THEN \'Best shoppers (high rfm)\' WHEN token IN (\'occasion\',\'occasion shoppers\', \'occassion\', \'onam\') THEN \'Occasion shoppers\' WHEN token IN (\'time specific app users\',\'time specific\', \'behavior - time specific\') THEN \'Time specific app users\' WHEN token IN (\'streak\',\'streaks\',\'x perks\',\'bau perks\',\'benefits\',\'coins\',\'coins expiry\',\'x customers bau\',\'snitch x coins\', \'x streaks\') THEN \'X members\' ELSE NULL END AS l1, CASE WHEN token IN (\'category\', \'collecction\', \'collection\') THEN \'Category\' WHEN token IN (\'boxers\',\'blazers\',\'belts\',\'co-ords\',\'inner wear\',\'perfumes\',\'bags\',\'shirts\', \'sunglasses\',\'hoodies\',\'joggers & track\',\'joggers & trackpants\',\'joggers\',\'sweatshirts\', \'pyjamas\',\'cargo pants\',\'jackets\',\'shoes\',\'sneakers\',\'sweaters\',\'overshirt\', \'shorts\',\'t-shirts\',\'tshirt\',\'tshirts\',\'shirt\',\'cshirt\',\'jeans\',\'trousers\', \'core labs\',\'corelabs\',\'elevated essentials\',\'office ready\',\'snitch luxe\',\'streetwear\', \'cart\',\'cart category\',\'luxe wear\',\'luxewear\', \'new\',\'new arrivals\',\'wtw\',\'daily wtw\',\'x wtw\',\'bestsellers\', \'checks\') THEN \'Category\' WHEN token IN (\'capsule\',\'stars within\',\'utopia\') THEN \'Capsule\' WHEN token IN (\'fathers day\',\'ganesh chaturthi\',\'rakhi\',\'valentine sale\',\'diwali sale\', \'christmas sale\',\'holi sale\', \'occassion\', \'onam\') THEN \'Occasion\' WHEN token IN (\'sale\',\'mega sale\',\'minor sale\',\'featured sale\',\'black friday sale\',\'black friday\', \'deal of the day\',\'dod\',\'under 999\',\'independence day sale\',\'snitch birthday sale\', \'right to snitch\', \'shop your size store\',\'behavior - size\',\'cutsize\',\'cutsize store\',\'xs\',\'s\',\'m\',\'l\',\'xl\',\'xxl\',\'large\') THEN \'Sale\' WHEN token IN (\'x perks\',\'bau perks\',\'benefits\',\'coins\',\'coins expiry\',\'x customers bau\',\'streak\',\'streaks\') THEN \'BAU Perks\' WHEN token IN (\'offer\',\'offers\',\'15% off or lower\',\'20% off\',\'25% off\',\'15% off\',\'20% off\',\'25% off\') THEN \'Offers\' WHEN token IN (\'homepage\',\'home page\') THEN \'Home page\' WHEN token = \'nso\' THEN \'NSO\' ELSE NULL END AS l2, CASE WHEN token IN (\'shirts\',\'shirt\',\'cshirt\', \'checks\') THEN \'Shirts\' WHEN token IN (\'tshirt\',\'tshirts\') THEN \'T-Shirts\' WHEN token IN (\'jeans\',\'denim wear\', \'skinny jeans\') THEN \'Jeans\' WHEN token IN (\'shoes\',\'sneakers\',\'footwear\') THEN \'Shoes\' WHEN token IN (\'core labs\',\'corelabs\') THEN \'Core Labs\' WHEN token IN (\'elevated essentials\', \'elevated-essentials\') THEN \'Elevated Essentials\' WHEN token = \'office ready\' THEN \'Office ready\' WHEN token = \'streetwear\' THEN \'Streetwear\' WHEN token = \'essentials\' THEN \'Essentials\' WHEN token = \'snitch luxe\' THEN \'Luxewear\' WHEN token IN (\'cart\',\'cart category\') THEN \'Cart category\' WHEN token IN (\'new\',\'new arrivals\') THEN \'New\' WHEN token IN (\'wtw\',\'daily wtw\',\'x wtw\') THEN \'WTW\' WHEN token IN (\'bestsellers\',\'bestseller\') THEN \'Bestsellers\' WHEN token = \'stars within\' THEN \'Stars Within\' WHEN token = \'utopia\' THEN \'Utopia\' WHEN token = \'snitch birthday sale\' THEN \'Snitch Birthday sale\' WHEN token IN (\'black friday sale\',\'black friday\') THEN \'Black Friday sale\' WHEN token IN (\'independence day sale\', \'right to snitch\') THEN \'Independence Day sale\' WHEN token = \'christmas sale\' THEN \'Christmas sale\' WHEN token = \'holi sale\' THEN \'Holi sale\' WHEN token = \'onam\' THEN \'Onam Sale\' WHEN token = \'diwali sale\' THEN \'Diwali sale\' WHEN token = \'valentine sale\' THEN \'Valentine sale\' WHEN token IN (\'dod\',\'deal of the day\') THEN \'Deal of the day\' WHEN token = \'under 999\' THEN \'Under 999\' WHEN token IN (\'behavior - size\',\'cutsize\',\'cutsize store\',\'xs\',\'s\',\'m\',\'l\',\'xl\',\'xxl\',\'large\') THEN \'Shop your size store\' WHEN token IN (\'x perks\',\'bau perks\') THEN \'BAU perks\' WHEN token IN (\'coins\',\'coins expiry\',\'snitch x coins\') THEN \'Coins\' WHEN token IN (\'streak\',\'streaks\', \'x streaks\') THEN \'Streaks\' WHEN token IN (\'boxers\',\'blazers\',\'belts\',\'co-ords\',\'inner wear\',\'perfumes\',\'bags\', \'sunglasses\',\'hoodies\',\'joggers & track\',\'joggers & trackpants\',\'sweatshirts\', \'pyjamas\',\'cargo pants\',\'jackets\',\'sweaters\',\'overshirt\',\'shorts\') THEN INITCAP(token) ELSE NULL END AS l3_bucket, CASE WHEN token IN (\'linen\',\'linen shirts\',\'linen edit\') THEN \'Linen\' WHEN token = \'pshirts\' THEN \'Plain\' WHEN token IN (\'checks\', \'cshirt\') THEN \'Checks\' WHEN token IN (\'sjeans\', \'skinny jeans\') THEN \'Skinny\' WHEN token IN (\'stripes\') THEN \'Stripes\' WHEN token IN (\'bjeans\', \'baggy\') THEN \'Baggy\' WHEN token = \'graphics\' THEN \'Graphics\' WHEN token IN (\'xs\',\'s\',\'m\',\'l\',\'xl\',\'xxl\',\'large\') THEN CASE token WHEN \'xs\' THEN \'XS\' WHEN \'s\' THEN \'S\' WHEN \'m\' THEN \'M\' WHEN \'l\' THEN \'L\' WHEN \'xl\' THEN \'XL\' WHEN \'xxl\' THEN \'XXL\' WHEN \'large\' THEN \'L\' END ELSE NULL END AS l4, CASE WHEN token=\'cross-sell\' THEN \'Cross sell\' WHEN token=\'upsell\' THEN \'Upsell\' WHEN token = \'msg91\' THEN \'msg91\' WHEN token = \'onextel\' THEN \'onextel\' ELSE NULL END AS l5, CASE WHEN token IN (\'pshirts\',\'sjeans\',\'bjeans\',\'linen\',\'linen shirts\',\'linen edit\',\'stripes\',\'revolution\') THEN \'Category\' WHEN token IN (\'behavior - size\',\'cutsize\',\'cutsize store\',\'xs\',\'s\',\'m\',\'l\',\'xl\',\'xxl\',\'large\',\'dod\',\'deal of the day\') THEN \'Sale\' WHEN token IN (\'coins\',\'coins expiry\', \'snitch x coins\', \'x streaks\') THEN \'BAU Perks\' WHEN token IN (\'stars within\',\'utopia\') THEN \'Capsule\' ELSE NULL END AS l2_bfill, CASE WHEN token IN (\'pshirts\', \'graphics\') THEN \'T-Shirts\' WHEN token IN (\'sjeans\',\'bjeans\') THEN \'Jeans\' WHEN token IN (\'linen\',\'linen shirts\',\'linen edit\', \'stripes\') THEN \'Shirts\' WHEN token IN (\'behavior - size\',\'cutsize\',\'cutsize store\',\'xs\',\'s\',\'m\',\'l\',\'xl\',\'xxl\',\'large\') THEN \'Shop your size store\' WHEN token IN (\'dod\',\'deal of the day\') THEN \'Deal of the day\' WHEN token IN (\'coins\',\'coins expiry\') THEN \'Coins\' WHEN token=\'new arrivals\' THEN \'New\' WHEN token IN (\'wtw\',\'daily wtw\',\'x wtw\') THEN \'WTW\' WHEN token=\'bestsellers\' THEN \'Bestsellers\' WHEN token=\'stars within\' THEN \'Stars Within\' WHEN token=\'revolution\' THEN \'Revolution\' WHEN token=\'utopia\' THEN \'Utopia\' WHEN token IN (\'streak\',\'streaks\') THEN \'Streaks\' ELSE NULL END AS l3_bfill FROM tok ), rolled AS ( SELECT campaign_id, run_date, channel, MAX(l1) AS label_1, COALESCE(MAX(l2), MAX(l2_bfill)) AS label_2, COALESCE( MAX(CASE WHEN l2 IS NOT NULL THEN l3_bucket END), MAX(l3_bfill) ) AS label_3, MAX(l4) AS label_4, MAX(l5) AS label_5, LISTAGG(DISTINCT CASE WHEN COALESCE(l1,l2,l3_bucket,l4,l5,l2_bfill,l3_bfill) IS NULL THEN token ELSE NULL END, \', \' ) AS unmapped_labels FROM classified GROUP BY campaign_id, run_date, channel ) SELECT * FROM rolled ORDER BY campaign_id, run_date );",
                    "transaction": true
                }
            ) }}
